const MANIFEST = {
  "type": "Interactive.GenerativeParticleUniverse",
  "description": "Mesmerizing interactive particle system with physics simulation, mouse forces, particle trails, multiple visual modes, and stunning generative aesthetics. The ultimate showcase of animation mastery.",
  "editorElement": {
    "selector": ".particle-universe",
    "displayName": "Generative Particle Universe",
    "archetype": "container",
    "data": {
      "particleCount": {
        "dataType": "select",
        "displayName": "Particle Count",
        "defaultValue": "150",
        "options": ["50", "100", "150", "200", "300"],
        "group": "Particles",
        "description": "Number of particles in the system"
      },
      "particleMode": {
        "dataType": "select",
        "displayName": "Visual Mode",
        "defaultValue": "constellation",
        "options": ["constellation", "aurora", "fireflies", "stardust", "nebula", "quantum"],
        "group": "Particles",
        "description": "Visual style preset"
      },
      "particleSize": {
        "dataType": "select",
        "displayName": "Particle Size",
        "defaultValue": "3",
        "options": ["1", "2", "3", "4", "5"],
        "group": "Particles"
      },
      "connectionDistance": {
        "dataType": "select",
        "displayName": "Connection Distance",
        "defaultValue": "120",
        "options": ["80", "100", "120", "150", "180"],
        "group": "Particles",
        "description": "Max distance for particle connections"
      },
      "showConnections": {
        "dataType": "booleanValue",
        "displayName": "Show Connections",
        "defaultValue": "true",
        "group": "Particles"
      },
      "showTrails": {
        "dataType": "booleanValue",
        "displayName": "Show Trails",
        "defaultValue": "true",
        "group": "Particles"
      },
      "trailLength": {
        "dataType": "select",
        "displayName": "Trail Length",
        "defaultValue": "0.15",
        "options": ["0.05", "0.1", "0.15", "0.2", "0.3"],
        "group": "Particles",
        "description": "Trail fade speed (lower = longer trails)"
      },
      "mouseForce": {
        "dataType": "select",
        "displayName": "Mouse Force",
        "defaultValue": "attract",
        "options": ["attract", "repel", "orbit", "none"],
        "group": "Physics",
        "description": "How particles react to cursor"
      },
      "mouseRadius": {
        "dataType": "select",
        "displayName": "Mouse Influence Radius",
        "defaultValue": "150",
        "options": ["80", "100", "150", "200", "250"],
        "group": "Physics"
      },
      "mouseStrength": {
        "dataType": "select",
        "displayName": "Mouse Force Strength",
        "defaultValue": "0.5",
        "options": ["0.2", "0.35", "0.5", "0.7", "1.0"],
        "group": "Physics"
      },
      "baseSpeed": {
        "dataType": "select",
        "displayName": "Base Speed",
        "defaultValue": "0.5",
        "options": ["0.2", "0.35", "0.5", "0.7", "1.0"],
        "group": "Physics"
      },
      "friction": {
        "dataType": "select",
        "displayName": "Friction",
        "defaultValue": "0.98",
        "options": ["0.95", "0.97", "0.98", "0.99", "0.995"],
        "group": "Physics",
        "description": "Velocity damping (higher = less friction)"
      },
      "turbulence": {
        "dataType": "select",
        "displayName": "Turbulence",
        "defaultValue": "0.3",
        "options": ["0", "0.1", "0.2", "0.3", "0.5"],
        "group": "Physics",
        "description": "Random motion intensity"
      },
      "pulseEffect": {
        "dataType": "booleanValue",
        "displayName": "Pulse Effect",
        "defaultValue": "true",
        "group": "Effects"
      },
      "glowIntensity": {
        "dataType": "select",
        "displayName": "Glow Intensity",
        "defaultValue": "medium",
        "options": ["none", "subtle", "medium", "intense"],
        "group": "Effects"
      },
      "colorCycle": {
        "dataType": "booleanValue",
        "displayName": "Color Cycling",
        "defaultValue": "false",
        "group": "Effects"
      },
      "colorCycleSpeed": {
        "dataType": "select",
        "displayName": "Color Cycle Speed",
        "defaultValue": "0.5",
        "options": ["0.2", "0.5", "1.0", "2.0"],
        "group": "Effects"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0a0a0f",
        "group": "Colors"
      },
      "primaryColor": {
        "dataType": "color",
        "displayName": "Primary Particle Color",
        "defaultValue": "#6366f1",
        "group": "Colors"
      },
      "secondaryColor": {
        "dataType": "color",
        "displayName": "Secondary Color",
        "defaultValue": "#8b5cf6",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#06b6d4",
        "group": "Colors"
      },
      "connectionColor": {
        "dataType": "color",
        "displayName": "Connection Line Color",
        "defaultValue": "#6366f1",
        "group": "Colors"
      },
      "showControls": {
        "dataType": "booleanValue",
        "displayName": "Show Controls",
        "defaultValue": "true",
        "group": "Content"
      },
      "showFPS": {
        "dataType": "booleanValue",
        "displayName": "Show FPS Counter",
        "defaultValue": "false",
        "group": "Content"
      },
      "canvasHeight": {
        "dataType": "select",
        "displayName": "Canvas Height",
        "defaultValue": "600",
        "options": ["400", "500", "600", "700", "800"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const canvasRef = React.useRef(null);
  const animationRef = React.useRef(null);
  const particlesRef = React.useRef([]);
  const mouseRef = React.useRef({ x: null, y: null, isActive: false });
  const timeRef = React.useRef(0);
  const fpsRef = React.useRef({ frames: 0, lastTime: performance.now(), current: 60 });

  const [isPaused, setIsPaused] = React.useState(false);
  const [currentFPS, setCurrentFPS] = React.useState(60);

  // Config with defaults
  const particleCount = parseInt(config?.particleCount || '150');
  const particleMode = config?.particleMode || 'constellation';
  const particleSize = parseFloat(config?.particleSize || '3');
  const connectionDistance = parseInt(config?.connectionDistance || '120');
  const showConnections = config?.showConnections !== false;
  const showTrails = config?.showTrails !== false;
  const trailLength = parseFloat(config?.trailLength || '0.15');
  const mouseForce = config?.mouseForce || 'attract';
  const mouseRadius = parseInt(config?.mouseRadius || '150');
  const mouseStrength = parseFloat(config?.mouseStrength || '0.5');
  const baseSpeed = parseFloat(config?.baseSpeed || '0.5');
  const friction = parseFloat(config?.friction || '0.98');
  const turbulence = parseFloat(config?.turbulence || '0.3');
  const pulseEffect = config?.pulseEffect !== false;
  const glowIntensity = config?.glowIntensity || 'medium';
  const colorCycle = config?.colorCycle === true;
  const colorCycleSpeed = parseFloat(config?.colorCycleSpeed || '0.5');
  const backgroundColor = config?.backgroundColor || '#0a0a0f';
  const primaryColor = config?.primaryColor || '#6366f1';
  const secondaryColor = config?.secondaryColor || '#8b5cf6';
  const accentColor = config?.accentColor || '#06b6d4';
  const connectionColor = config?.connectionColor || '#6366f1';
  const showControls = config?.showControls !== false;
  const showFPS = config?.showFPS === true;
  const canvasHeight = parseInt(config?.canvasHeight || '600');

  // Reduced motion check
  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined' 
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
      : false;
  }, []);

  // Color utilities
  const hexToRgb = React.useCallback((hex) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : { r: 99, g: 102, b: 241 };
  }, []);

  const hslToRgb = React.useCallback((h, s, l) => {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = n => {
      const k = (n + h / 30) % 12;
      return l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    };
    return { r: Math.round(f(0) * 255), g: Math.round(f(8) * 255), b: Math.round(f(4) * 255) };
  }, []);

  // Mode-specific configurations
  const getModeConfig = React.useCallback((mode) => {
    const configs = {
      constellation: {
        sizeVariation: 0.5,
        speedVariation: 0.3,
        connectionOpacity: 0.4,
        particleOpacity: 0.9,
        glowMultiplier: 1,
        trailOpacity: 0.3
      },
      aurora: {
        sizeVariation: 0.8,
        speedVariation: 0.5,
        connectionOpacity: 0.2,
        particleOpacity: 0.7,
        glowMultiplier: 1.5,
        trailOpacity: 0.5
      },
      fireflies: {
        sizeVariation: 0.6,
        speedVariation: 0.7,
        connectionOpacity: 0.1,
        particleOpacity: 1,
        glowMultiplier: 2,
        trailOpacity: 0.2
      },
      stardust: {
        sizeVariation: 0.9,
        speedVariation: 0.2,
        connectionOpacity: 0.15,
        particleOpacity: 0.85,
        glowMultiplier: 1.2,
        trailOpacity: 0.4
      },
      nebula: {
        sizeVariation: 1.2,
        speedVariation: 0.4,
        connectionOpacity: 0.3,
        particleOpacity: 0.6,
        glowMultiplier: 1.8,
        trailOpacity: 0.6
      },
      quantum: {
        sizeVariation: 0.4,
        speedVariation: 0.9,
        connectionOpacity: 0.5,
        particleOpacity: 0.95,
        glowMultiplier: 0.8,
        trailOpacity: 0.15
      }
    };
    return configs[mode] || configs.constellation;
  }, []);

  const modeConfig = React.useMemo(() => getModeConfig(particleMode), [getModeConfig, particleMode]);

  // Glow configuration
  const glowConfig = React.useMemo(() => {
    const configs = {
      none: { blur: 0, spread: 0 },
      subtle: { blur: 4, spread: 2 },
      medium: { blur: 8, spread: 4 },
      intense: { blur: 15, spread: 8 }
    };
    return configs[glowIntensity] || configs.medium;
  }, [glowIntensity]);

  // Initialize particles
  const initParticles = React.useCallback((width, height) => {
    const particles = [];
    const colors = [primaryColor, secondaryColor, accentColor];

    for (let i = 0; i < particleCount; i++) {
      const colorIndex = Math.floor(Math.random() * colors.length);
      const rgb = hexToRgb(colors[colorIndex]);
      const sizeMod = 1 + (Math.random() - 0.5) * modeConfig.sizeVariation;
      const speedMod = 1 + (Math.random() - 0.5) * modeConfig.speedVariation;

      particles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * baseSpeed * speedMod,
        vy: (Math.random() - 0.5) * baseSpeed * speedMod,
        size: particleSize * sizeMod,
        baseSize: particleSize * sizeMod,
        color: rgb,
        colorIndex,
        hue: Math.random() * 360,
        pulseOffset: Math.random() * Math.PI * 2,
        opacity: modeConfig.particleOpacity * (0.7 + Math.random() * 0.3),
        life: 1,
        trail: []
      });
    }

    return particles;
  }, [particleCount, particleSize, baseSpeed, primaryColor, secondaryColor, accentColor, hexToRgb, modeConfig]);

  // Physics update
  const updateParticle = React.useCallback((particle, width, height, time) => {
    const mouse = mouseRef.current;

    // Apply turbulence
    if (turbulence > 0) {
      particle.vx += (Math.random() - 0.5) * turbulence * 0.1;
      particle.vy += (Math.random() - 0.5) * turbulence * 0.1;
    }

    // Mouse interaction
    if (mouse.isActive && mouse.x !== null && mouseForce !== 'none') {
      const dx = mouse.x - particle.x;
      const dy = mouse.y - particle.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < mouseRadius && dist > 0) {
        const force = (1 - dist / mouseRadius) * mouseStrength;
        const angle = Math.atan2(dy, dx);

        switch (mouseForce) {
          case 'attract':
            particle.vx += Math.cos(angle) * force;
            particle.vy += Math.sin(angle) * force;
            break;
          case 'repel':
            particle.vx -= Math.cos(angle) * force * 1.5;
            particle.vy -= Math.sin(angle) * force * 1.5;
            break;
          case 'orbit':
            const orbitAngle = angle + Math.PI / 2;
            particle.vx += Math.cos(orbitAngle) * force * 0.8;
            particle.vy += Math.sin(orbitAngle) * force * 0.8;
            // Slight pull toward center
            particle.vx += Math.cos(angle) * force * 0.2;
            particle.vy += Math.sin(angle) * force * 0.2;
            break;
        }
      }
    }

    // Apply friction
    particle.vx *= friction;
    particle.vy *= friction;

    // Speed limit
    const speed = Math.sqrt(particle.vx * particle.vx + particle.vy * particle.vy);
    const maxSpeed = baseSpeed * 5;
    if (speed > maxSpeed) {
      particle.vx = (particle.vx / speed) * maxSpeed;
      particle.vy = (particle.vy / speed) * maxSpeed;
    }

    // Store trail position
    if (showTrails) {
      particle.trail.unshift({ x: particle.x, y: particle.y });
      if (particle.trail.length > 10) {
        particle.trail.pop();
      }
    }

    // Update position
    particle.x += particle.vx;
    particle.y += particle.vy;

    // Wrap around edges
    if (particle.x < -50) particle.x = width + 50;
    if (particle.x > width + 50) particle.x = -50;
    if (particle.y < -50) particle.y = height + 50;
    if (particle.y > height + 50) particle.y = -50;

    // Pulse effect
    if (pulseEffect) {
      const pulse = Math.sin(time * 0.003 + particle.pulseOffset) * 0.3 + 1;
      particle.size = particle.baseSize * pulse;
    }

    // Color cycling
    if (colorCycle) {
      particle.hue = (particle.hue + colorCycleSpeed * 0.5) % 360;
    }

    return particle;
  }, [mouseForce, mouseRadius, mouseStrength, friction, turbulence, baseSpeed, showTrails, pulseEffect, colorCycle, colorCycleSpeed]);

  // Render frame
  const render = React.useCallback((ctx, width, height, time) => {
    const particles = particlesRef.current;

    // Clear or fade for trails
    if (showTrails) {
      ctx.fillStyle = `rgba(${hexToRgb(backgroundColor).r}, ${hexToRgb(backgroundColor).g}, ${hexToRgb(backgroundColor).b}, ${trailLength})`;
      ctx.fillRect(0, 0, width, height);
    } else {
      ctx.fillStyle = backgroundColor;
      ctx.fillRect(0, 0, width, height);
    }

    // Draw connections
    if (showConnections) {
      const connRgb = hexToRgb(connectionColor);

      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < connectionDistance) {
            const opacity = (1 - dist / connectionDistance) * modeConfig.connectionOpacity;
            ctx.beginPath();
            ctx.strokeStyle = `rgba(${connRgb.r}, ${connRgb.g}, ${connRgb.b}, ${opacity})`;
            ctx.lineWidth = 1;
            ctx.moveTo(particles[i].x, particles[i].y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.stroke();
          }
        }
      }
    }

    // Draw particles
    particles.forEach((particle, index) => {
      let color;
      if (colorCycle) {
        color = hslToRgb(particle.hue, 70, 60);
      } else {
        color = particle.color;
      }

      // Draw trail
      if (showTrails && particle.trail.length > 1) {
        ctx.beginPath();
        ctx.moveTo(particle.trail[0].x, particle.trail[0].y);

        for (let i = 1; i < particle.trail.length; i++) {
          const trailOpacity = (1 - i / particle.trail.length) * modeConfig.trailOpacity;
          ctx.strokeStyle = `rgba(${color.r}, ${color.g}, ${color.b}, ${trailOpacity})`;
          ctx.lineWidth = particle.size * (1 - i / particle.trail.length);
          ctx.lineTo(particle.trail[i].x, particle.trail[i].y);
        }
        ctx.stroke();
      }

      // Draw glow
      if (glowConfig.blur > 0) {
        const gradient = ctx.createRadialGradient(
          particle.x, particle.y, 0,
          particle.x, particle.y, particle.size * glowConfig.spread * modeConfig.glowMultiplier
        );
        gradient.addColorStop(0, `rgba(${color.r}, ${color.g}, ${color.b}, ${particle.opacity * 0.5})`);
        gradient.addColorStop(1, `rgba(${color.r}, ${color.g}, ${color.b}, 0)`);

        ctx.beginPath();
        ctx.fillStyle = gradient;
        ctx.arc(particle.x, particle.y, particle.size * glowConfig.spread * modeConfig.glowMultiplier, 0, Math.PI * 2);
        ctx.fill();
      }

      // Draw particle
      ctx.beginPath();
      ctx.fillStyle = `rgba(${color.r}, ${color.g}, ${color.b}, ${particle.opacity})`;
      ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
      ctx.fill();

      // Highlight center for fireflies mode
      if (particleMode === 'fireflies') {
        ctx.beginPath();
        ctx.fillStyle = `rgba(255, 255, 255, ${particle.opacity * 0.8})`;
        ctx.arc(particle.x, particle.y, particle.size * 0.4, 0, Math.PI * 2);
        ctx.fill();
      }
    });

    // Draw mouse influence area (subtle)
    const mouse = mouseRef.current;
    if (mouse.isActive && mouse.x !== null && mouseForce !== 'none') {
      const gradient = ctx.createRadialGradient(
        mouse.x, mouse.y, 0,
        mouse.x, mouse.y, mouseRadius
      );
      const mouseColor = mouseForce === 'repel' ? '255, 100, 100' : 
                        mouseForce === 'orbit' ? '100, 255, 200' : '100, 150, 255';
      gradient.addColorStop(0, `rgba(${mouseColor}, 0.05)`);
      gradient.addColorStop(0.5, `rgba(${mouseColor}, 0.02)`);
      gradient.addColorStop(1, `rgba(${mouseColor}, 0)`);

      ctx.beginPath();
      ctx.fillStyle = gradient;
      ctx.arc(mouse.x, mouse.y, mouseRadius, 0, Math.PI * 2);
      ctx.fill();
    }
  }, [backgroundColor, showConnections, connectionDistance, connectionColor, showTrails, trailLength, glowConfig, particleMode, colorCycle, hexToRgb, hslToRgb, mouseForce, mouseRadius, modeConfig]);

  // Animation loop
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;

    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const width = rect.width;
    const height = rect.height;

    // Initialize particles
    particlesRef.current = initParticles(width, height);

    const animate = (timestamp) => {
      if (isPaused || prefersReducedMotion) {
        animationRef.current = requestAnimationFrame(animate);
        return;
      }

      timeRef.current = timestamp;

      // FPS calculation
      fpsRef.current.frames++;
      if (timestamp - fpsRef.current.lastTime >= 1000) {
        fpsRef.current.current = fpsRef.current.frames;
        fpsRef.current.frames = 0;
        fpsRef.current.lastTime = timestamp;
        if (showFPS) setCurrentFPS(fpsRef.current.current);
      }

      // Update particles
      particlesRef.current = particlesRef.current.map(p => 
        updateParticle(p, width, height, timestamp)
      );

      // Render
      render(ctx, width, height, timestamp);

      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [initParticles, updateParticle, render, isPaused, prefersReducedMotion, showFPS]);

  // Mouse handlers
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        isActive: true
      };
    };

    const handleMouseLeave = () => {
      mouseRef.current = { x: null, y: null, isActive: false };
    };

    const handleTouchMove = (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: touch.clientX - rect.left,
        y: touch.clientY - rect.top,
        isActive: true
      };
    };

    const handleTouchEnd = () => {
      mouseRef.current = { x: null, y: null, isActive: false };
    };

    canvas.addEventListener('mousemove', handleMouseMove);
    canvas.addEventListener('mouseleave', handleMouseLeave);
    canvas.addEventListener('touchmove', handleTouchMove, { passive: false });
    canvas.addEventListener('touchend', handleTouchEnd);

    return () => {
      canvas.removeEventListener('mousemove', handleMouseMove);
      canvas.removeEventListener('mouseleave', handleMouseLeave);
      canvas.removeEventListener('touchmove', handleTouchMove);
      canvas.removeEventListener('touchend', handleTouchEnd);
    };
  }, []);

  // Resize handler
  React.useEffect(() => {
    const handleResize = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;

      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;

      const ctx = canvas.getContext('2d');
      ctx.scale(dpr, dpr);

      // Redistribute particles
      particlesRef.current = particlesRef.current.map(p => ({
        ...p,
        x: Math.min(p.x, rect.width),
        y: Math.min(p.y, rect.height)
      }));
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleReset = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    particlesRef.current = initParticles(rect.width, rect.height);
  };

  // Static display for reduced motion
  if (prefersReducedMotion) {
    return (
      <div
        className="particle-universe"
        style={{
          position: 'relative',
          width: '100%',
          height: canvasHeight + 'px',
          backgroundColor: backgroundColor,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
          color: primaryColor,
          borderRadius: '8px',
          overflow: 'hidden'
        }}
      >
        <div style={{ textAlign: 'center', padding: '40px' }}>
          <div style={{ 
            fontSize: 'clamp(24px, 4vw, 36px)', 
            fontWeight: '300',
            marginBottom: '12px',
            letterSpacing: '0.02em'
          }}>
            Particle Universe
          </div>
          <div style={{ 
            fontSize: '14px', 
            opacity: 0.6,
            fontWeight: '400'
          }}>
            Animation paused for reduced motion preference
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      className="particle-universe"
      style={{
        position: 'relative',
        width: '100%',
        height: canvasHeight + 'px',
        backgroundColor: backgroundColor,
        borderRadius: '8px',
        overflow: 'hidden',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          cursor: mouseForce !== 'none' ? 'crosshair' : 'default'
        }}
      />

      {/* FPS Counter */}
      {showFPS && (
        <div
          style={{
            position: 'absolute',
            top: '12px',
            left: '12px',
            padding: '6px 10px',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            borderRadius: '4px',
            fontSize: '12px',
            fontWeight: '500',
            color: currentFPS >= 55 ? '#4ade80' : currentFPS >= 30 ? '#fbbf24' : '#f87171',
            fontFamily: 'monospace',
            letterSpacing: '0.05em'
          }}
        >
          {currentFPS} FPS
        </div>
      )}

      {/* Mode indicator */}
      <div
        style={{
          position: 'absolute',
          top: '12px',
          right: '12px',
          padding: '8px 14px',
          backgroundColor: 'rgba(0, 0, 0, 0.4)',
          backdropFilter: 'blur(8px)',
          borderRadius: '20px',
          fontSize: '11px',
          fontWeight: '500',
          color: 'rgba(255, 255, 255, 0.8)',
          textTransform: 'uppercase',
          letterSpacing: '0.1em'
        }}
      >
        {particleMode}
      </div>

      {/* Controls */}
      {showControls && (
        <div
          style={{
            position: 'absolute',
            bottom: '16px',
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            gap: '12px',
            padding: '10px 16px',
            backgroundColor: 'rgba(0, 0, 0, 0.4)',
            backdropFilter: 'blur(12px)',
            borderRadius: '30px',
            border: '1px solid rgba(255, 255, 255, 0.1)'
          }}
        >
          <button
            onClick={() => setIsPaused(!isPaused)}
            aria-label={isPaused ? 'Play' : 'Pause'}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              padding: '8px 16px',
              borderRadius: '20px',
              fontSize: '13px',
              fontWeight: '500',
              color: 'rgba(255, 255, 255, 0.9)',
              backgroundColor: isPaused ? 'rgba(255, 255, 255, 0.15)' : 'transparent',
              transition: 'all 200ms ease'
            }}
            onMouseEnter={(e) => {
              e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
            }}
            onMouseLeave={(e) => {
              e.target.style.backgroundColor = isPaused ? 'rgba(255, 255, 255, 0.15)' : 'transparent';
            }}
          >
            {isPaused ? '▶ Play' : '⏸ Pause'}
          </button>

          <button
            onClick={handleReset}
            aria-label="Reset particles"
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              padding: '8px 16px',
              borderRadius: '20px',
              fontSize: '13px',
              fontWeight: '500',
              color: 'rgba(255, 255, 255, 0.9)',
              transition: 'all 200ms ease'
            }}
            onMouseEnter={(e) => {
              e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
            }}
            onMouseLeave={(e) => {
              e.target.style.backgroundColor = 'transparent';
            }}
          >
            ↻ Reset
          </button>
        </div>
      )}

      {/* Interaction hint */}
      {mouseForce !== 'none' && (
        <div
          style={{
            position: 'absolute',
            bottom: showControls ? '70px' : '16px',
            left: '50%',
            transform: 'translateX(-50%)',
            fontSize: '11px',
            color: 'rgba(255, 255, 255, 0.4)',
            textAlign: 'center',
            pointerEvents: 'none',
            letterSpacing: '0.05em'
          }}
        >
          Move cursor to {mouseForce} particles
        </div>
      )}
    </div>
  );
}

