      "flowSpeed": {
        "dataType": "select",
        "displayName": "Flow Speed",
        "defaultValue": "1.0",
        "options": ["0.5", "0.75", "1.0", "1.5", "2.0"],
        "group": "Animation"
      },
      "noiseScale": {
        "dataType": "select",
        "displayName": "Noise Scale",
        "defaultValue": "0.005",
        "options": ["0.003", "0.005", "0.008", "0.01"],
        "group": "Animation"
      },
      "noiseEvolution": {
        "dataType": "select",
        "displayName": "Noise Evolution Speed",
        "defaultValue": "0.0005",
        "options": ["0.0002", "0.0005", "0.001", "0.002"],
        "group": "Animation"
      },
      "trailLength": {
