function Component({ config = {} }) {
  const count = parseInt(config?.particleCount || "99");
  const duration = parseInt(config?.animationDuration || "5");
  const stagger = parseFloat(config?.staggerDelay || "-0.05");
  const spiralMult = parseInt(config?.spiralMultiplier || "10");
  const startScale = parseFloat(config?.startScale || "1.1");
  const rotation = parseFloat(config?.rotationAmount || "-3");
  const particleSize = config?.particleSize || "medium";
  const clickToPause = config?.clickToPause !== false;
  const bgColor = config?.backgroundColor || "#FFFFFF";
  const particleColor = config?.particleColor || "#495057";

  const canvasRef = React.useRef(null);
  const particlesRef = React.useRef([]);
  const timeRef = React.useRef(0);
  const [isPaused, setIsPaused] = React.useState(false);
  const [imagesLoaded, setImagesLoaded] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  // Size mapping
  const sizeMap = {
    small: 0.6,
    medium: 1.0,
    large: 1.4
  };
  const sizeMultiplier = sizeMap[particleSize] || 1.0;

  // Create particle shape as data URL (simple circle)
  const createParticleImage = () => {
    const size = 40;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    // Draw circle
    ctx.fillStyle = particleColor;
    ctx.beginPath();
    ctx.arc(size/2, size/2, size/2 - 2, 0, Math.PI * 2);
    ctx.fill();

    return canvas.toDataURL();
  };

  // Initialize particles (exact replica of original logic)
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let cw = canvas.width = window.innerWidth;
    let ch = canvas.height = window.innerHeight;
    let radius = Math.max(cw, ch);

    const particleDataURL = createParticleImage();

    // Create particles
    const particles = [];
    let loadedCount = 0;

    for (let i = 0; i < count; i++) {
      const img = new Image();
      img.onload = () => {
        loadedCount++;
        if (loadedCount === count) {
          setImagesLoaded(true);
        }
      };
      img.src = particleDataURL;

      const angle = (i / count * Math.PI * 2) - Math.PI / 2;

      particles[i] = {
        x: Math.cos(angle * spiralMult) * radius,
        y: Math.sin(angle * spiralMult) * radius,
        startX: Math.cos(angle * spiralMult) * radius,
        startY: Math.sin(angle * spiralMult) * radius,
        scale: startScale,
        rotate: 0,
        img: img
      };
    }

    particlesRef.current = particles;

    const handleResize = () => {
      cw = canvas.width = window.innerWidth;
      ch = canvas.height = window.innerHeight;
      radius = Math.max(cw, ch);

      // Update particle start positions
      particlesRef.current.forEach((p, i) => {
        const angle = (i / count * Math.PI * 2) - Math.PI / 2;
        p.startX = Math.cos(angle * spiralMult) * radius;
        p.startY = Math.sin(angle * spiralMult) * radius;
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [count, spiralMult, startScale, particleColor]);

  // Animation loop (exact replica)
  React.useEffect(() => {
    if (prefersReducedMotion || !imagesLoaded) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let startTime = Date.now();
    let animationFrame;

    const animate = () => {
      if (!isPaused) {
        const elapsed = (Date.now() - startTime) / 1000;
        const progress = (elapsed % (duration + Math.abs(stagger * count))) / duration;

        // Update each particle (exact GSAP timeline replica)
        particlesRef.current.forEach((p, i) => {
          const delay = i * stagger;
          const particleProgress = Math.max(0, Math.min(1, progress - (delay / duration)));

          // Sine easing (matching GSAP "sine")
          const eased = Math.sin(particleProgress * Math.PI / 2);

          // Animate from start position to center (0, 0)
          p.x = p.startX + (0 - p.startX) * eased;
          p.y = p.startY + (0 - p.startY) * eased;
          p.scale = startScale + (0 - startScale) * eased;
          p.rotate = rotation * eased;
        });
      }

      draw(ctx, canvas);
      animationFrame = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      if (animationFrame) cancelAnimationFrame(animationFrame);
    };
  }, [isPaused, duration, count, stagger, rotation, startScale, imagesLoaded, prefersReducedMotion]);

  // Draw function (exact replica)
  const draw = (ctx, canvas) => {
    const cw = canvas.width;
    const ch = canvas.height;

    // Clear
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, cw, ch);

    // Sort by scale for z-indexing (exact replica)
    const sorted = [...particlesRef.current].sort((a, b) => a.scale - b.scale);

    // Draw particles
    sorted.forEach(p => {
      ctx.save();
      ctx.translate(cw / 2, ch / 2);
      ctx.rotate(p.rotate);

      const drawWidth = p.img.width * p.scale * sizeMultiplier;
      const drawHeight = p.img.height * p.scale * sizeMultiplier;

      ctx.drawImage(
        p.img,
        p.x - drawWidth / 2,
        p.y - drawHeight / 2,
        drawWidth,
        drawHeight
      );

      ctx.restore();
    });
  };

  const handleClick = () => {
    if (clickToPause) {
      setIsPaused(!isPaused);
    }
  };

  return (
    <div
      className="canvas-particles-replica"
      style={{
        position: 'relative',
        width: '100%',
        height: '100vh',
        backgroundColor: bgColor,
        overflow: 'hidden'
      }}
    >
      <canvas
        ref={canvasRef}
        onClick={handleClick}
        style={{
          display: 'block',
          width: '100%',
          height: '100%',
          cursor: clickToPause ? 'pointer' : 'default'
        }}
      />

      {clickToPause && (
        <div
          style={{
            position: 'absolute',
            bottom: '20px',
            left: '50%',
            transform: 'translateX(-50%)',
            fontSize: '14px',
            color: particleColor,
            opacity: 0.6,
            userSelect: 'none',
            pointerEvents: 'none'
          }}
        >
          {isPaused ? 'Click to play' : 'Click to pause'}
        </div>
      )}
    </div>
  );
}
